import {PROTOCOL_DATA} from './protocol-data.js';
import {CATALOG} from './catalog.js';
import {OPERATORS,STRATEGIES,MAPS,DIFFICULTIES,ROMAN} from './data.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const portrait=o=>{const file=PROTOCOL_DATA.assets?.[o.charId||o.id];if(file)return `<img src="./${file}" alt="" loading="lazy">`;const local=OPERATORS.find(x=>x.name===o.name);return local?`<img src="./assets/${local.id}-avatar.png" alt="">`:`<span class="portrait-fallback">${esc(o.name.slice(0,1))}</span>`;};
const nav=(title,subtitle='GARRISON PROTOCOL')=>`<header class="screen-nav"><button data-act="home" aria-label="返回大厅">‹</button><div><small>${subtitle}</small><h1>${title}</h1></div><span class="prototype-label">交互原型 · 演示规则</span></header>`;
export function catalogCards(query='',profession='all'){
 const rows=CATALOG.filter(o=>(profession==='all'||o.profession===profession)&&(!query||o.name.toLowerCase().includes(query.toLowerCase())||o.id.includes(query)));
 return `<div class="catalog-count">${rows.length} 名干员 <span>原作档案 · 当前数据库快照</span></div><div class="catalog-grid">${rows.map(o=>`<button class="catalog-card" data-act="catalog-detail" data-id="${o.id}">${portrait(o)}<div class="catalog-rarity">${'★'.repeat(o.rarity)}</div><strong>${esc(o.name)}</strong><span>${esc(o.profession)} / ${esc(o.branch)}</span>${!o.historical?'<small>下半期之后新增</small>':''}</button>`).join('')||'<p class="empty-state">没有符合条件的干员，试试其他名称或职业。</p>'}</div>`;
}
export function screenMarkup(view,game,options={}){
 const s=game.s;
 if(view==='home')return `<section class="lobby"><div class="lobby-top"><span>RHODES ISLAND / S.W.E.E.P.</span><button data-act="about">版本说明</button></div><div class="lobby-art" aria-hidden="true"><span class="protocol-sigil">⌘</span><div class="art-line"></div></div><div class="lobby-title"><p>GARRISON PROTOCOL</p><h1>卫戍协议<span>盟约</span></h1><div class="lobby-edition">下半期 · 原作界面与交互原型</div><p class="lobby-note">配置物资，构筑阵线，完成防卫模拟。</p></div><div class="lobby-menu"><button class="lobby-main" data-act="${s.phase==='briefing'?'setup':'return-battle'}"><span>${s.phase==='briefing'?'开始模拟':'继续模拟'}</span><b>→</b><small>${s.phase==='briefing'?'INDEPENDENT SIMULATION':`第 ${s.round} 轮 / ${s.phase==='battle'?'作战中':'整备与决策'}`}</small></button><button data-act="roster"><span>物资调配处</span><small>配置演示阵容与技能</small><b>↗</b></button><button data-act="database"><span>原作数据库</span><small>${CATALOG.length} 名干员 / 技能与模组</small><b>↗</b></button><button data-act="season"><span>下半期协议资料</span><small>本期干员、盟约、装备与地图</small><b>↗</b></button><button data-act="room"><span>同盟模拟</span><small>房间界面预览</small><b>↗</b></button><button data-act="help"><span>操作说明</span><small>部署、交换、装备与取消</small><b>↗</b></button></div><footer class="lobby-footer"><span>PRTS 资料库已接入 · 原作战斗规则校准进行中</span><span>LOCAL / OFFLINE</span></footer></section>`;
 if(view==='setup')return nav('选择模拟协议')+`<div class="setup-layout"><section class="setup-intro"><p class="screen-kicker">01 / SIMULATION</p><h2>独立模拟</h2><p>先选择演示难度与地图，随后查看战前简报并选择初始策略。</p><div class="mode-scope">当前战斗使用已有单人演示规则。下半期全部难度与玩法将在后续阶段接入。</div><button data-act="room">查看同盟房间 →</button></section><section><div class="difficulty-options">${Object.entries(DIFFICULTIES).map(([id,d],i)=>`<button class="difficulty-option ${s.difficulty===id?'chosen':''}" data-act="difficulty" data-id="${id}"><span class="difficulty-number">0${i+1}</span><div><h3>${d.name}</h3><p>${d.desc}</p></div><b>${s.difficulty===id?'✓':'›'}</b></button>`).join('')}</div><h3 class="screen-label">演示战场</h3><div class="map-options">${MAPS.map((m,i)=>`<button data-act="map" data-value="${i}" class="${s.map===i?'chosen':''}"><small>${m.code}</small>${m.name}</button>`).join('')}</div><div class="screen-bottom"><span>演示地图 · 非原版关卡</span><button class="primary" data-act="briefing">确认协议 →</button></div></section></div>`;
 if(view==='briefing')return nav('模拟简报')+`<div class="brief-layout"><div class="brief-overview"><p class="screen-kicker">DEFENSE BRIEFING</p><h2>${MAPS[s.map].name}</h2><p>${DIFFICULTIES[s.difficulty].name} / 独立模拟</p><div class="brief-lines"><div><span>防卫进程</span><strong>16轮演示波次</strong></div><div><span>当前调配池</span><strong>${OPERATORS.length} 名</strong></div><div><span>初始部署位</span><strong>8</strong></div></div><p class="mode-scope">这一阶段验证页面与操作流程。这里展示的是现有演示对局，不代表原作最终配置。</p></div><section><h3 class="screen-label">选择初始策略</h3><div class="strategy-options">${STRATEGIES.map((st,i)=>`<button data-act="strategy" data-id="${st.id}" class="strategy-option ${s.strategy===st.id?'chosen':''}"><small>STRATEGY / 0${i+1}</small><h3>${st.name}</h3><p>${st.desc}</p><div>目标生命 <strong>${st.hp}</strong> <span>${s.strategy===st.id?'已选择':'选择'}</span></div></button>`).join('')}</div><div class="screen-bottom"><button data-act="setup">返回协议选择</button><button class="primary" data-act="begin">建立防线 →</button></div></section></div>`;
 if(view==='roster')return nav('物资调配处')+`<div class="screen-toolbar"><span>演示调配池 · ${OPERATORS.length} 名干员</span><button data-act="database">浏览完整原作数据库 →</button></div><p class="screen-description">以下干员已接入当前演示规则。等阶固定；点击查看技能并配置携带方案。</p>${[1,2,3,4,5,6].map(t=>`<section class="tier-section"><h2>${ROMAN[t]} <small>等阶</small></h2><div class="loadout-grid">${OPERATORS.filter(o=>o.tier===t).map(o=>`<button data-act="operator" data-id="${o.id}" class="loadout-card">${portrait(o)}<div><strong>${o.name}</strong><span>${o.skills[s.skillPrefs[o.id]||0].name}</span></div></button>`).join('')}</div></section>`).join('')}<div class="screen-bottom"><span>实际战斗数值以演示干员详情为准</span><button class="primary" data-act="${s.phase==='briefing'?'setup':'return-battle'}">${s.phase==='briefing'?'前往模拟':'返回阵地'} →</button></div>`;
 if(view==='database')return nav('干员数据库','PRTS / OPERATOR ARCHIVE')+`<div class="screen-toolbar"><input id="catalog-search" aria-label="搜索干员" placeholder="搜索干员名称或内部 ID" value="${esc(options.query||'')}"><div class="profession-filter">${['all','先锋','近卫','重装','狙击','术师','医疗','辅助','特种'].map(p=>`<button data-act="catalog-filter" data-id="${p}" class="${(options.profession||'all')===p?'chosen':''}">${p==='all'?'全部':p}</button>`).join('')}</div></div><div id="catalog-results">${catalogCards(options.query,options.profession)}</div>`;
 if(view==='catalog-detail'){
 const o=CATALOG.find(x=>x.id===options.id);if(!o)return nav('未找到干员')+'<p class="empty-state">该条目不存在。请返回数据库重新选择。</p>';
 return nav(o.name,'PRTS / VERIFIED SOURCE DATA')+`<div class="archive-detail"><aside>${portrait(o)}<h2>${esc(o.name)}</h2><p>${o.profession} / ${o.branch}</p><p class="archive-id">${o.id}</p><span class="data-badge">${o.historical?'存在于下半期历史快照':'下半期之后新增'}</span><p class="mode-scope">原作档案数值，不自动替换当前演示战斗。历史快照存在不等于进入该期调配池。</p><a href="${esc(o.source)}" target="_blank" rel="noreferrer">查看来源 ↗</a></aside><section><h3 class="screen-label">最高精英阶段 / 满级基础属性</h3><div class="archive-stats">${[['生命上限',o.stats.maxHp],['攻击',o.stats.atk],['防御',o.stats.def],['法术抗性',o.stats.magicResistance],['攻击间隔',o.stats.baseAttackTime+'s'],['再部署',o.stats.respawnTime+'s']].map(([k,v])=>`<div><small>${k}</small><strong>${v??'—'}</strong></div>`).join('')}</div><h3 class="screen-label">技能 / 专精上限数据</h3>${o.skills.map(sk=>`<article class="archive-skill"><div><h3>${esc(sk.name)}</h3><span>${sk.recovery==='INCREASE_WITH_TIME'?'自动回复':sk.recovery==='INCREASE_WHEN_ATTACK'?'攻击回复':sk.recovery==='INCREASE_WHEN_TAKEN_DAMAGE'?'受击回复':esc(sk.recovery)} · ${sk.activation==='MANUAL'?'手动触发':'自动触发'}</span></div><p>初始技力 ${sk.initialSP} / 消耗 ${sk.sp} / 持续 ${sk.duration}s</p><p class="skill-description">${esc(sk.description)}</p><details class="raw-data"><summary>原始参数 / 扩展制作参考</summary><div class="blackboard">${sk.blackboard.map(b=>`<span>${esc(b.key)} <b>${b.value??esc(b.valueStr)}</b></span>`).join('')}</div></details></article>`).join('')||'<p class="empty-state">此干员没有主动技能。</p>'}<h3 class="screen-label">专属模组</h3>${o.modules.map(m=>`<article class="archive-skill"><h3>${esc(m.name)}</h3><p>${m.levels.map(l=>'Lv.'+l.level+' '+l.attributes.map(a=>a.key+' +'+a.value).join(' / ')).join('<br>')}</p></article>`).join('')||'<p class="empty-state">当前快照没有专属模组。</p>'}<button data-act="database">返回干员列表</button></section></div>`;
 }
 if(view==='season'){
 const tab=options.tab||'operators',p=PROTOCOL_DATA,labels={operators:'干员',enemies:'敌人',bonds:'盟约',bands:'策略',items:'装备',modes:'难度',maps:'地图'};let body='';
 if(tab==='operators')body=p.roster.map(o=>`<details class="season-entry"><summary>${portrait(o)}<span class="season-tier">${ROMAN[o.rank]}</span><strong>${esc(o.name)}</strong><span>${o.normal.bonds.map(id=>p.bonds.find(b=>b.id===id)?.name||id).join(' / ')}</span></summary><div class="season-state-grid">${[['初始',o.normal],['精锐',o.elite]].map(([name,state])=>`<section><h3>${name} · ${state.status.evolvePhase.replace('PHASE_','精英')} Lv.${state.status.charLevel}</h3><p>生命 ${state.attributes.maxHp} / 攻击 ${state.attributes.atk} / 防御 ${state.attributes.def}</p><p>技能：${esc(state.skill||'无主动技能')} · Rank ${state.status.skillLevel}</p>${state.garrisons.map(g=>`<p class="season-description">${esc(g)}</p>`).join('')}</section>`).join('')}</div></details>`).join('');
 if(tab==='bonds')body=p.bonds.map(b=>`<details class="season-entry"><summary><strong>${esc(b.name)}</strong><span>${b.count} 名激活</span></summary><p class="season-description">${esc(b.description)}</p></details>`).join('');
 if(tab==='bands')body=p.bands.map(b=>`<details class="season-entry"><summary>${p.assets[b.id]?`<img src="./${p.assets[b.id]}" alt="" loading="lazy">`:""}<strong>${esc(b.name)}</strong><span>初始生命 ${b.hp}</span></summary><p class="season-description">${esc(b.description)}</p></details>`).join('');
 if(tab==='items')body=p.items.filter(i=>!i.hidden).map(i=>`<details class="season-entry"><summary><span class="season-tier">${ROMAN[i.rank]||'—'}</span><strong>${esc(i.name)}</strong><span>${i.price} 资金</span></summary><p class="season-description">${esc(i.description||'效果描述见原始记录，执行机制仍需逐项接入。')}</p></details>`).join('');
 if(tab==='enemies')body=p.enemies.map(e=>`<details class="season-entry"><summary><img src="./${p.assets[e.id]}" alt="" loading="lazy"><strong>${esc(e.name)}</strong><span>${e.kinds.map(k=>({'random-pool':'常规池','mode-effect':'策略／悬赏','template':'生成模板'}[k])).join(' / ')}</span><span>${e.data.motion==='FLY'?'飞行':'地面'} / ${e.data.applyWay==='RANGED'?'远程攻击':e.data.applyWay==='NONE'?'不攻击':'近战攻击'}</span></summary><p>生命 ${e.data.attributes.maxHp} / 攻击 ${e.data.attributes.atk} / 防御 ${e.data.attributes.def} / 法抗 ${e.data.attributes.magicResistance}</p><p>攻击间隔 ${e.data.attributes.baseAttackTime}s · 移速 ${e.data.attributes.moveSpeed}</p>${e.ability.map(a=>`<p>${esc(a.text)}</p>`).join('')}<p class="small muted">本期敌人基准值${e.modifiedForMode?'，已应用卫戍专属覆盖':''}；逐轮生成与难度修正另算。${e.excludedModes.includes('mode_single_funny')?'标准／险境不出现此敌人。':''}</p><details class="raw-data"><summary>原始能力参数</summary><pre>${esc(JSON.stringify({skills:e.data.skills,talentBlackboard:e.data.talentBlackboard},null,2))}</pre></details></details>`).join('');
 if(tab==='modes')body=p.modes.map(m=>`<section class="season-entry"><h3>${m.code} / ${m.name}</h3><p>${esc(m.desc)}</p><p>${m.rounds.length} 轮配置${m.rounds.some(r=>r.isConditional)?'（含条件回合）':''} · 基础资金：第1轮4，此后每轮+1</p><table class="season-table"><thead><tr><th>商店等级</th><th>干员栏</th><th>装备栏</th><th>初始升级费用</th></tr></thead><tbody>${m.shopLevels.map(l=>`<tr><td>${l.level}</td><td>${l.operatorSlots}</td><td>${l.itemSlots}</td><td>${l.upgradeCost??'满级'}</td></tr>`).join('')}</tbody></table></section>`).join('');
 if(tab==='maps')body=p.maps.map(m=>`<section class="season-entry"><h3>${m.stageId} ${m.weight===0?'（未投入随机池）':''}</h3><div class="native-map" style="grid-template-columns:repeat(${m.cols},1fr)">${m.grid.flat().map(t=>`<span class="native-tile ${t.buildableType==='NONE'?'tile-disabled':t.heightType==='HIGHLAND'?'tile-high':'tile-ground'}" title="${esc(t.tileKey)}"></span>`).join('')}</div><p>${m.cols} × ${m.rows} · 原始左侧常规战场裁切</p></section>`).join('');
 return nav('盟约 · 下半期','ACT2AUTOCHESS / NATIVE DATA')+`<div class="season-intro"><strong>本期数据已归档，完整玩法仍在接入</strong><p>112 条可见预设、215 条敌人引用（含常规池、策略／悬赏与模板）、23 个盟约、40 条策略和 8 张有效地图。数值来源为固定历史表；基础资金来源为用户确认。尚未实现的技能和效果不会被当作已完成。</p></div><div class="profession-filter season-tabs">${Object.entries(labels).map(([id,name])=>`<button data-act="season-tab" data-id="${id}" class="${id===tab?'chosen':''}">${name}</button>`).join('')}</div><div class="screen-toolbar"><input id="season-search" type="search" aria-label="搜索本期资料" placeholder="搜索名称或效果"></div><div class="season-content">${body}</div>`;
 }
 if(view==='room')return nav('同盟模拟')+`<section class="room-view"><p class="screen-kicker">ALLIANCE / ROOM PREVIEW</p><h2>建立互助战线</h2><div class="room-slots">${[0,1,2,3].map(i=>`<div class="room-slot ${i===0?'occupied':''}"><span>${i===0?'⌘':'+'}</span><strong>${i===0?'本地博士':'等待成员'}</strong><small>${i===0?'界面预览':'EMPTY SLOT'}</small></div>`).join('')}</div><p class="mode-scope">房间服务与同盟规则属于S7，本页面仅展示成员与准备状态，尚未连接其他玩家。</p><button disabled title="同盟服务尚未实现">创建在线房间</button><button data-act="home">返回大厅</button></section>`;
 return '';
}
